    tls: ['l3-tls-order', 'l3-mtls', 'l3-zscaler', 'l6-zscaler'],
    nat: ['l2-snat', 'l2-nat-placement', 'l2-stable-egress', 'l2-default-route', 'l2-nacl-ephemeral'],
